import sys
prog=[]
for l in open(sys.argv[1]):
    l=l.split(';')[0].strip()
    if l: prog.append(l.split())
R=dict(a=0,b=0,c=0,d=0)
v=lambda x:R[x] if x in R else int(x)
pc=0;n=0;tot=0;outs=[]
while 0<=pc<len(prog):
    i=prog[pc];op=i[0];n+=1;nx=pc+1
    if op=='set':R[i[1]]=v(i[2])%65536
    elif op=='add':R[i[1]]=(R[i[1]]+v(i[2]))%65536
    elif op=='mul':R[i[1]]=(R[i[1]]*v(i[2]))%65536
    elif op=='mod':
        x=v(i[2])
        if x>0:R[i[1]]%=x
    elif op=='dec':R[i[1]]=max(0,R[i[1]]-1)
    elif op=='jnz':
        if v(i[1])!=0:nx=pc+v(i[2])
    elif op=='skp':
        if v(i[1])<v(i[2]):nx=pc+2
    elif op=='out':outs.append(v(i[1]));tot+=v(i[1])
    else:raise Exception(i)
    pc=nx
print(tot,n,len(outs))
open('answer.txt','w').write(f"{tot} {n}\n")
E
